            if active_cost <= fallback_threshold * min_other:
                if active_cost < fallback_active_cost:
                    fallback_index = i
                    fallback_active_cost = active_cost

    if best_index is not None:
        return best_index
    elif fallback_index is not None:
        return fallback_index
